"""
Module for managing kernels.

"""

import json
import logging
import subprocess
import sys
from pathlib import Path
from typing import Any, Optional

from jupyter_client.kernelspec import KernelSpecManager

from qbraid_core.system.executables import is_exe

from .paths import find_python_in_env, installed_envs_data

logger = logging.getLogger(__name__)


def _get_kernels_path(environment: str) -> Path:
    """Get the path to the kernels directory for the given environment.

    Args:
        environment: Environment name (if unique) or env_id

    Returns:
        Path to kernels directory
    """
    env_id_to_path, name_to_env_id = installed_envs_data()

    # Try to find by name first, then by env_id
    env_id = None
    if environment in name_to_env_id:
        env_id = name_to_env_id.get(environment, None)
    else:
        # Assume it's an env_id
        env_id = environment

    if env_id not in env_id_to_path:
        raise ValueError(
            f"Environment '{environment}' not found. "
            "Use name (if unique) or env_id to reference the environment."
        )

    env_path = env_id_to_path[env_id]
    kernels_path = env_path / "kernels"
    return kernels_path


def get_all_kernels(
    exclude_invalid: bool = False, exclude_kernels: Optional[list[str]] = None
) -> dict[str, Any]:
    """
    Returns a dictionary mapping kernel names to kernelspecs, with options to
    exclude certain kernels.

    Args:
        exclude_invalid (bool): If True, kernels with non-executable paths are excluded.
        exclude_kernels (list[str], optional): List of kernel names to exclude.

    Returns:
        dict[str, Any]: A dictionary of kernel names to their corresponding kernelspec details.
    """
    kernel_spec_manager = KernelSpecManager()
    kernelspecs = kernel_spec_manager.get_all_specs()

    # Filter out deprecated or unwanted kernels
    kernelspecs = {k: v for k, v in kernelspecs.items() if k not in (exclude_kernels or [])}

    # Optionally remove kernels with non-executable paths
    if exclude_invalid:
        for kernel_name, spec in list(kernelspecs.items()):
            try:
                exe_path = spec["spec"]["argv"][0]
                if not is_exe(exe_path):
                    raise ValueError("Invalid executable path.")
            except (KeyError, IndexError, TypeError, ValueError):
                kernel_spec_manager.remove_kernel_spec(kernel_name)
                kernelspecs.pop(kernel_name, None)

    return kernelspecs


def find_orphaned_kernels() -> list[dict[str, Any]]:
    """Find Jupyter kernels whose Python executable no longer exists.

    Scans all installed kernelspecs and checks if the argv[0] Python path
    exists and is executable.

    Returns:
        List of dicts with keys: name, resource_dir, python_path, reason.
    """
    kernel_spec_manager = KernelSpecManager()
    kernelspecs = kernel_spec_manager.get_all_specs()

    orphaned = []
    for kernel_name, spec in kernelspecs.items():
        # Skip the default python3 kernel
        if kernel_name == "python3":
            continue

        try:
            argv = spec["spec"]["argv"]
            if not argv:
                orphaned.append(
                    {
                        "name": kernel_name,
                        "resource_dir": spec.get("resource_dir", ""),
                        "python_path": "",
                        "reason": "Empty argv in kernel.json",
                    }
                )
                continue

            python_path = argv[0]
            if not Path(python_path).exists():
                orphaned.append(
                    {
                        "name": kernel_name,
                        "resource_dir": spec.get("resource_dir", ""),
                        "python_path": python_path,
                        "reason": "Python path does not exist",
                    }
                )
            elif not is_exe(python_path):
                orphaned.append(
                    {
                        "name": kernel_name,
                        "resource_dir": spec.get("resource_dir", ""),
                        "python_path": python_path,
                        "reason": "Python path is not executable",
                    }
                )
        except (KeyError, IndexError, TypeError):
            orphaned.append(
                {
                    "name": kernel_name,
                    "resource_dir": spec.get("resource_dir", ""),
                    "python_path": "",
                    "reason": "Invalid kernel.json structure",
                }
            )

    return orphaned


def remove_kernel_by_name(kernel_name: str) -> bool:
    """Remove a single kernel by its kernelspec name.

    Args:
        kernel_name: The kernelspec name (e.g., "python3_myenv_a1b2").

    Returns:
        True if removed, False if not found.
    """
    kernel_spec_manager = KernelSpecManager()
    kernelspecs = kernel_spec_manager.get_all_specs()

    if kernel_name not in kernelspecs:
        return False

    kernel_spec_manager.remove_kernel_spec(kernel_name)
    return True


def add_kernels(environment: str) -> None:
    """Add a kernel to user's Jupyter kernel directory."""
    kernel_spec_manager = KernelSpecManager()
    kernels_path = _get_kernels_path(environment)

    # Use user=True to install to user-level data directory
    # This ensures kernels are found regardless of virtualenv setup
    for kernel in kernels_path.iterdir():
        kernel_spec_manager.install_kernel_spec(source_dir=str(kernel), user=True)


def _is_path_inside(child: Path, parent: Path) -> bool:
    """Return True if ``child`` resolves to a path under ``parent``.

    Both paths are ``.resolve()``-d so symlinked launchers (a common shape:
    ``/opt/conda/bin/python -> <env>/pyenv/bin/python``) still register as
    being inside the env. Non-existent paths are resolved lexically on
    Python ≥3.6, so a stale kernelspec argv[0] pointing at a since-deleted
    env still returns True as long as the paths line up textually after
    normalization.
    """
    try:
        child_resolved = Path(child).resolve()
        parent_resolved = Path(parent).resolve()
    except (OSError, RuntimeError):
        return False
    try:
        return child_resolved.is_relative_to(parent_resolved)
    except ValueError:  # different drives on Windows
        return False


def _find_kernels_referencing_env(env_path: Path) -> list[str]:
    """Return kernelspec names whose launcher ``argv[0]`` lives inside ``env_path``.

    Catches kernels registered outside ``<env>/kernels/`` that still point at
    the env's Python — most commonly the extras that env-startup ``.pth``
    hooks write into ``jupyter_data_dir()`` (see
    ``docs/bundling-native-deps-and-kernels.md`` §6, e.g. xeus-cling C++
    kernels), but also anything a user manually registered with
    ``python -m ipykernel install --prefix=<env>``.
    """
    referencing: list[str] = []
    try:
        specs = KernelSpecManager().get_all_specs()
        for kernel_name, spec in specs.items():
            if kernel_name == "python3":
                # Belt-and-suspenders: `/usr/bin/python3` isn't under any env
                # dir so the path check already excludes it, but skipping by
                # name makes the intent explicit and avoids ever nuking the
                # system default even if a future env path collision were
                # somehow possible.
                continue
            try:
                argv = spec["spec"]["argv"]
                if not argv:
                    continue
                if _is_path_inside(Path(argv[0]), env_path):
                    referencing.append(kernel_name)
            except (KeyError, IndexError, TypeError):
                continue
    except Exception as err:  # pylint: disable=broad-exception-caught
        logger.warning("Could not enumerate kernelspecs for sweep: %s", err)

    return referencing


def remove_kernels(environment: str) -> list[str]:
    """Remove all Jupyter kernelspecs associated with a qBraid environment.

    Removes two categories:
    1. Kernels the qBraid installer wrote into ``<env>/kernels/`` (the standard
       Python kernel, one per env).
    2. Kernels **self-registered by env-startup hooks** anywhere else in
       Jupyter's kernel search path, detected by ``argv[0]`` pointing inside
       the env directory (see ``docs/bundling-native-deps-and-kernels.md`` §6
       — extra kernels like xeus-cling that a ``.pth`` writes into
       ``jupyter_data_dir()``).

    Args:
        environment: Environment name (if unique) or env_id.

    Returns:
        Names of every kernelspec that was removed. Empty list is a valid
        outcome (env had no registered kernels).
    """
    kernel_spec_manager = KernelSpecManager()
    kernels_path = _get_kernels_path(environment)
    env_path = kernels_path.parent

    removed: list[str] = []

    # 1. Kernels the qBraid installer wrote to <env>/kernels/ — remove by name.
    if kernels_path.exists():
        for kernel in kernels_path.iterdir():
            try:
                kernel_spec_manager.remove_kernel_spec(kernel.name)
                removed.append(kernel.name)
            except Exception as err:  # pylint: disable=broad-exception-caught
                logger.warning("Failed to remove kernelspec %s: %s", kernel.name, err)

    # 2. Kernels self-registered outside <env>/kernels/ but whose launcher
    #    lives inside the env directory. Deduped against #1 so a spec that
    #    the installer wrote AND was later moved isn't reported twice.
    for kernel_name in _find_kernels_referencing_env(env_path):
        if kernel_name in removed:
            continue
        try:
            kernel_spec_manager.remove_kernel_spec(kernel_name)
            removed.append(kernel_name)
        except Exception as err:  # pylint: disable=broad-exception-caught
            logger.warning(
                "Failed to remove orphan kernelspec %s (argv[0] inside %s): %s",
                kernel_name,
                env_path,
                err,
            )

    return removed


def is_kernel_installed(environment: str) -> bool:
    """Check if environment's kernel is installed in Jupyter.

    This checks if the kernel is actually installed in Jupyter's kernel spec
    directories (user or system level), not just if the kernel.json exists
    in the environment's kernels/ directory.

    Args:
        environment: Environment name (if unique) or env_id

    Returns:
        True if kernel is installed in Jupyter, False otherwise
    """
    try:
        kernels_path = _get_kernels_path(environment)
    except ValueError:
        return False

    if not kernels_path.exists():
        return False

    # Get all installed Jupyter kernels
    kernel_spec_manager = KernelSpecManager()
    installed_kernels = kernel_spec_manager.get_all_specs()

    # Check if any kernel from this environment is installed
    for kernel_dir in kernels_path.iterdir():
        if kernel_dir.is_dir() and kernel_dir.name in installed_kernels:
            return True

    return False


def validate_kernel(env_path: Path) -> tuple[bool, str]:
    """Validate that kernel.json has a working Python path.

    Args:
        env_path: Path to environment directory (contains kernels/)

    Returns:
        tuple[bool, str]: (is_valid, message)
            - is_valid: True if kernel has valid Python path
            - message: Description of validation result
    """
    kernels_dir = env_path / "kernels"

    if not kernels_dir.exists():
        return False, "No kernels directory found"

    for kernel_dir in kernels_dir.iterdir():
        if not kernel_dir.is_dir():
            continue

        kernel_json = kernel_dir / "kernel.json"
        if not kernel_json.exists():
            continue

        try:
            with open(kernel_json, "r", encoding="utf-8") as f:
                data = json.load(f)

            if "argv" not in data or not data["argv"]:
                return False, f"kernel.json at {kernel_dir.name} has no argv"

            python_path = Path(data["argv"][0])

            # Check if path exists
            if not python_path.exists():
                if python_path.is_symlink():
                    try:
                        target = python_path.resolve()
                        return False, f"Broken Python symlink: {python_path} -> {target}"
                    except OSError:
                        return False, f"Cannot resolve Python symlink: {python_path}"
                return False, f"Python path does not exist: {python_path}"

            # Check if Python executable works
            if not is_exe(python_path):
                return False, f"Python path is not executable: {python_path}"

            # Try to run Python
            try:
                result = subprocess.run(
                    [str(python_path), "--version"],
                    capture_output=True,
                    timeout=10,
                    check=False,
                )
                if result.returncode != 0:
                    return False, f"Python fails to run: {result.stderr.decode()}"
            except (subprocess.TimeoutExpired, OSError) as err:
                return False, f"Cannot execute Python: {err}"

            return True, f"Kernel {kernel_dir.name} has valid Python at {python_path}"

        except (json.JSONDecodeError, OSError) as err:
            return False, f"Cannot read kernel.json at {kernel_dir.name}: {err}"

    return False, "No valid kernel.json found"


def repair_kernel(env_path: Path, python_path: Optional[Path] = None) -> tuple[bool, str]:
    """Update kernel.json with correct Python path.

    If python_path is not provided, attempts to find Python in the environment's
    pyenv/bin directory.

    Args:
        env_path: Path to environment directory (contains kernels/)
        python_path: Optional explicit Python path to use

    Returns:
        tuple[bool, str]: (success, message)
    """
    kernels_dir = env_path / "kernels"

    if not kernels_dir.exists():
        return False, "No kernels directory found"

    # Find Python executable if not provided
    if python_path is None:
        detected = find_python_in_env(env_path, validate=True)
        if detected:
            python_path = Path(detected)
        else:
            # Try common locations
            pyenv_path = env_path / "pyenv"
            if sys.platform == "win32":
                candidates = [
                    pyenv_path / "Scripts" / "python.exe",
                    env_path / "Scripts" / "python.exe",
                ]
            else:
                candidates = [
                    pyenv_path / "bin" / "python",
                    env_path / "bin" / "python",
                    pyenv_path / "bin" / "python3",
                    env_path / "bin" / "python3",
                ]

            for candidate in candidates:
                if candidate.exists():
                    python_path = candidate
                    break

    if python_path is None:
        return False, "Cannot find Python executable in environment"

    repaired = False
    messages = []

    for kernel_dir in kernels_dir.iterdir():
        if not kernel_dir.is_dir():
            continue

        kernel_json = kernel_dir / "kernel.json"
        if not kernel_json.exists():
            continue

        try:
            with open(kernel_json, "r", encoding="utf-8") as f:
                data = json.load(f)

            if "argv" in data and data["argv"]:
                old_path = data["argv"][0]
                if old_path != str(python_path):
                    data["argv"][0] = str(python_path)
                    with open(kernel_json, "w", encoding="utf-8") as f:
                        json.dump(data, f, indent=1)
                    messages.append(f"Updated {kernel_dir.name}: {old_path} -> {python_path}")
                    repaired = True
                else:
                    messages.append(f"{kernel_dir.name} already has correct path")

        except (json.JSONDecodeError, OSError) as err:
            messages.append(f"Failed to update {kernel_dir.name}: {err}")

    if not messages:
        return False, "No kernel.json files found to repair"

    return repaired, "; ".join(messages)


def ensure_ipykernel(env_path: Path, env_id: Optional[str] = None) -> tuple[bool, str]:
    """Install ipykernel if not present in the environment.

    Args:
        env_path: Path to environment directory
        env_id: Optional environment ID. If provided, uses pip_install which
            also updates the registry. If not provided, attempts to find env_id
            from registry by path.

    Returns:
        tuple[bool, str]: (success, message)
    """
    from .packages import pip_install
    from .registry import EnvironmentRegistryManager

    # Find Python executable
    python_path = find_python_in_env(env_path, validate=True)
    if not python_path:
        return False, "Cannot find valid Python in environment"

    # Check if ipykernel is already installed
    try:
        result = subprocess.run(
            [python_path, "-c", "import ipykernel"],
            capture_output=True,
            timeout=30,
            check=False,
        )
        if result.returncode == 0:
            return True, "ipykernel is already installed"
    except (subprocess.TimeoutExpired, OSError) as err:
        return False, f"Cannot check ipykernel: {err}"

    # Try to find env_id if not provided (needed for pip_install)
    if env_id is None:
        try:
            registry = EnvironmentRegistryManager()
            found = registry.find_by_path(env_path)
            if found:
                env_id, _ = found
        except Exception:  # pylint: disable=broad-exception-caught
            pass  # Fall back to direct subprocess if registry lookup fails

    # Install ipykernel using pip_install if we have env_id
    if env_id:
        try:
            install_result = pip_install(env_id, ["ipykernel"])
            if install_result.get("success"):
                return True, "ipykernel installed successfully"
            return False, f"pip install failed: {install_result.get('output', 'Unknown error')}"
        except Exception as err:  # pylint: disable=broad-exception-caught
            return False, f"Failed to install ipykernel: {err}"

    # Fallback: direct subprocess if no env_id available
    try:
        result = subprocess.run(
            [python_path, "-m", "pip", "install", "ipykernel"],
            capture_output=True,
            timeout=300,  # 5 minutes for install
            check=False,
        )
        if result.returncode == 0:
            return True, "ipykernel installed successfully"
        return False, f"pip install failed: {result.stderr.decode()}"
    except (subprocess.TimeoutExpired, OSError) as err:
        return False, f"Failed to install ipykernel: {err}"


def download_kernel_logo(url: str, kernel_dir: Path, timeout: int = 10) -> bool:
    """Download logo from URL, save as logo-64x64.png and logo-32x32.png in kernel_dir.

    Args:
        url: URL to download the logo image from
        kernel_dir: Path to kernel resource directory
        timeout: Request timeout in seconds

    Returns:
        bool: True if download succeeded, False otherwise
    """
    import requests  # pylint: disable=import-outside-toplevel

    try:
        response = requests.get(url, timeout=timeout)
        response.raise_for_status()

        kernel_dir.mkdir(parents=True, exist_ok=True)
        for size in ["64x64", "32x32"]:
            dest_path = kernel_dir / f"logo-{size}.png"
            with open(dest_path, "wb") as f:
                f.write(response.content)
            logger.debug("Saved kernel logo to %s", dest_path)

        return True
    except Exception as err:  # pylint: disable=broad-exception-caught
        logger.warning("Failed to download kernel logo from %s: %s", url, err)
        return False


def create_kernel_spec(
    env_path: Path,
    kernel_name: str,
    display_name: str,
    env_id: Optional[str] = None,
    logo_url: Optional[str] = None,
) -> Path:
    """Create a kernel.json file for an environment.

    Args:
        env_path: Path to environment directory
        kernel_name: Internal kernel name (e.g., "python3_abc1")
        display_name: Display name shown in Jupyter
        env_id: Environment ID (used for kernel directory naming)
        logo_url: Optional URL to logo image to download

    Returns:
        Path to created kernel.json

    Raises:
        ValueError: If Python cannot be found in environment
    """
    # Find Python executable
    python_path = find_python_in_env(env_path, validate=True)
    if not python_path:
        raise ValueError(f"Cannot find valid Python in environment: {env_path}")

    # Create kernels directory structure
    kernels_dir = env_path / "kernels"
    kernel_dir_name = kernel_name if env_id is None else f"python3_{env_id}"
    kernel_dir = kernels_dir / kernel_dir_name
    kernel_dir.mkdir(parents=True, exist_ok=True)

    # Create kernel.json
    kernel_spec = {
        "argv": [python_path, "-m", "ipykernel_launcher", "-f", "{connection_file}"],
        "display_name": display_name,
        "language": "python",
    }

    kernel_json_path = kernel_dir / "kernel.json"
    with open(kernel_json_path, "w", encoding="utf-8") as f:
        json.dump(kernel_spec, f, indent=1)

    logger.info("Created kernel spec at %s", kernel_json_path)

    # Download logo if URL provided
    if logo_url:
        download_kernel_logo(logo_url, kernel_dir)

    return kernel_json_path


